import axios from 'axios'; import { IVulnerability } from '../db/models/Scan.model.js'; interface FileChange {   path: string;   content: string; } export class GitHubPRService {   private static readonly GITHUB_API_URL = 'https://api.github.com';   /**    * Create a pull request with security fixes    */   static async createSecurityFixPR(     repoFullName: string,     defaultBranch: string,     vulnerabilities: IVulnerability[],     accessToken: string   ): Promise&lt;{ prUrl: string; prNumber: number }&gt; {     try {       // Step 1: Get the latest commit SHA from the default branch       const refResponse = await axios.get(         `${this.GITHUB_API_URL}/repos/${repoFullName}/git/ref/heads/${defaultBranch}`,         {           headers: {             Authorization: `Bearer ${accessToken}`,             Accept: 'application/vnd.github.v3+json',           },         }       );       const latestCommitSha = refResponse.data.object.sha;       // Step 2: Create a new branch for the fixes       const branchName = `security-fixes-${Date.now()}`;       await axios.post(         `${this.GITHUB_API_URL}/repos/${repoFullName}/git/refs`,         {           ref: `refs/heads/${branchName}`,           sha: latestCommitSha,         },         {           headers: {             Authorization: `Bearer ${accessToken}`,             Accept: 'application/vnd.github.v3+json',           },         }       );       // Step 3: Get current file contents and apply fixes       const fileChanges = await this.prepareFileChanges(         repoFullName,         defaultBranch,         vulnerabilities,         accessToken       );       // Step 4: Commit changes to the new branch       for (const fileChange of fileChanges) {         await this.updateFile(           repoFullName,           branchName,           fileChange.path,           fileChange.content,           accessToken         );       }       // Step 5: Create pull request       const prTitle = `🔒 Security Fixes: ${vulnerabilities.length} vulnerabilities addressed`;       const prBody = this.generatePRDescription(vulnerabilities);       const prResponse = await axios.post(         `${this.GITHUB_API_URL}/repos/${repoFullName}/pulls`,         {           title: prTitle,           head: branchName,           base: defaultBranch,           body: prBody,         },         {           headers: {             Authorization: `Bearer ${accessToken}`,             Accept: 'application/vnd.github.v3+json',   // ... [File update &amp; tree commit methods] ...   /**    * Update a file in the repository    */   private static async updateFile(     repoFullName: string,     branch: string,     filePath: string,     content: string,     accessToken: string   ): Promise&lt;void&gt; {     try {       // Get current file SHA       const fileResponse = await axios.get(         `${this.GITHUB_API_URL}/repos/${repoFullName}/contents/${filePath}?ref=${branch}`,         {           headers: {             Authorization: `Bearer ${accessToken}`,             Accept: 'application/vnd.github.v3+json',           },         }       );       const fileSha = fileResponse.data.sha;       // Update file       await axios.put(         `${this.GITHUB_API_URL}/repos/${repoFullName}/contents/${filePath}`,         {           message: `fix: Security fix for ${filePath}`,           content: Buffer.from(content).toString('base64'),           sha: fileSha,           branch: branch,         },         {           headers: {             Authorization: `Bearer ${accessToken}`,             Accept: 'application/vnd.github.v3+json',           },         }       );     } catch (error: any) {       console.error(`Error updating file ${filePath}:`, error.response?.data || error.message);       throw error;     }   }   /**    * Generate PR description    */   private static generatePRDescription(vulnerabilities: IVulnerability[]): string {     const summary = {       critical: vulnerabilities.filter(v =&gt; v.severity === 'critical').length,       high: vulnerabilities.filter(v =&gt; v.severity === 'high').length,       medium: vulnerabilities.filter(v =&gt; v.severity === 'medium').length,       low: vulnerabilities.filter(v =&gt; v.severity === 'low').length,     };     let description = `## 🔒 Automated Security Fixes

`;     description += `This PR addresses **${vulnerabilities.length} security vulnerabilities** detected by VulnixAI.

`;
